insert into public.learning_chapters (id, module_key, sort_order, order_index, title_en, title_bm, intro_en, intro_bm) values ('848cf8e1-ee8d-4462-a285-56cf1d468a03', 'sd_client', 15, 15, 'Service Desk (My Services)', 'Service Desk (Servis Saya)', 'My Services is where your company sends work to the M-Core team under your service contract. Each request is tracked with its own SLA clock, status and files, and every month you get a report pack.', 'Servis Saya ialah tempat syarikat anda hantar kerja kepada pasukan M-Core di bawah kontrak servis. Setiap permohonan dijejak dengan jam SLA, status dan fail sendiri, dan setiap bulan anda terima pek laporan.')
 on conflict (id) do update set module_key=excluded.module_key, sort_order=excluded.sort_order, order_index=excluded.order_index, title_en=excluded.title_en, title_bm=excluded.title_bm, intro_en=excluded.intro_en, intro_bm=excluded.intro_bm, deleted_at=null;
insert into public.learning_lessons (id, chapter_id, sort_order, order_index, title_en, title_bm, intro_en, intro_bm) values ('28c2b0a4-e59b-452a-a2e8-bfc07162bad0', '848cf8e1-ee8d-4462-a285-56cf1d468a03', 1, 1, 'My Services: contract, quota & requests', 'Servis Saya: kontrak, kuota & permohonan', 'Read the contract card and request list first: they tell you how much quota is left and which requests need you.', 'Baca kad kontrak dan senarai permohonan dahulu: ia beritahu baki kuota dan permohonan mana yang perlukan anda.')
 on conflict (id) do update set chapter_id=excluded.chapter_id, sort_order=excluded.sort_order, order_index=excluded.order_index, title_en=excluded.title_en, title_bm=excluded.title_bm, intro_en=excluded.intro_en, intro_bm=excluded.intro_bm, deleted_at=null;
update public.learning_steps set text_en='The Service Contract card shows your contract period, SLA (business hours, Mon–Fri) and the monthly quota bar, e.g. 5 / 20 used this month.', text_bm='Kad Kontrak Servis tunjuk tempoh kontrak, SLA (jam bekerja, Isnin–Jumaat) dan bar kuota bulanan, cth 5 / 20 digunakan bulan ini.', field_note_en='Each request uses 1 quota when it is submitted; cancelled requests do not count.', field_note_bm='Setiap permohonan guna 1 kuota bila dihantar; permohonan dibatalkan tidak dikira.', try_it_page='servis_saya', image_path='lc-img/sd_client/my-services-1.webp', image_alt_en='Example screen (sample data): The Service Contract card shows your contract period, SLA (business hours, Mon–Fri) and the monthly quota bar, e.g. 5 / 20 used this month.', image_alt_bm='Contoh skrin (data contoh): Kad Kontrak Servis tunjuk tempoh kontrak, SLA (jam bekerja, Isnin–Jumaat) dan bar kuota bulanan, cth 5 / 20 digunakan bulan ini.', order_index=1, deleted_at=null where lesson_id='28c2b0a4-e59b-452a-a2e8-bfc07162bad0' and step_no=1;
insert into public.learning_steps (id, lesson_id, step_no, order_index, text_en, text_bm, field_note_en, field_note_bm, try_it_page, image_path, image_alt_en, image_alt_bm)
 select '44da273e-dbb2-47fc-a812-65144a00823e', '28c2b0a4-e59b-452a-a2e8-bfc07162bad0', 1, 1, 'The Service Contract card shows your contract period, SLA (business hours, Mon–Fri) and the monthly quota bar, e.g. 5 / 20 used this month.', 'Kad Kontrak Servis tunjuk tempoh kontrak, SLA (jam bekerja, Isnin–Jumaat) dan bar kuota bulanan, cth 5 / 20 digunakan bulan ini.', 'Each request uses 1 quota when it is submitted; cancelled requests do not count.', 'Setiap permohonan guna 1 kuota bila dihantar; permohonan dibatalkan tidak dikira.', 'servis_saya', 'lc-img/sd_client/my-services-1.webp', 'Example screen (sample data): The Service Contract card shows your contract period, SLA (business hours, Mon–Fri) and the monthly quota bar, e.g. 5 / 20 used this month.', 'Contoh skrin (data contoh): Kad Kontrak Servis tunjuk tempoh kontrak, SLA (jam bekerja, Isnin–Jumaat) dan bar kuota bulanan, cth 5 / 20 digunakan bulan ini.'
 where not exists (select 1 from public.learning_steps where lesson_id='28c2b0a4-e59b-452a-a2e8-bfc07162bad0' and step_no=1);
update public.learning_steps set text_en='The counters (In progress, Waiting, Delivered, Closed) and chips (All, Needs action, Delivered) filter the list. "Needs action" means M-Core is waiting on you or work was delivered for your check.', text_bm='Kaunter (Proses, Tunggu, Dihantar, Ditutup) dan cip (Semua, Perlu tindakan, Dihantar) menapis senarai. "Perlu tindakan" bermaksud M-Core menunggu anda atau kerja sudah dihantar untuk semakan anda.', field_note_en=NULL, field_note_bm=NULL, try_it_page='servis_saya', image_path='lc-img/sd_client/my-services-2.webp', image_alt_en='Example screen (sample data): The counters (In progress, Waiting, Delivered, Closed) and chips (All, Needs action, Delivered) filter the list. "Needs action" means M-Core', image_alt_bm='Contoh skrin (data contoh): Kaunter (Proses, Tunggu, Dihantar, Ditutup) dan cip (Semua, Perlu tindakan, Dihantar) menapis senarai. "Perlu tindakan" bermaksud M-Core men', order_index=2, deleted_at=null where lesson_id='28c2b0a4-e59b-452a-a2e8-bfc07162bad0' and step_no=2;
