update public.learning_steps set text_en='Tap a request to open its timeline: status changes, messages, files and the SLA clock. When work is Delivered, accept it (Close) or ask for a Revision.', text_bm='Tekan satu permohonan untuk buka garis masa: perubahan status, mesej, fail dan jam SLA. Bila kerja Dihantar, terima (Tutup) atau minta Revisi.', field_note_en='Delivered requests close automatically 7 days after delivery.', field_note_bm='Permohonan Dihantar ditutup automatik 7 hari selepas dihantar.', try_it_page='servis_saya', image_path='lc-img/sd_client/my-services-3.webp', image_alt_en='Example screen (sample data): Tap a request to open its timeline: status changes, messages, files and the SLA clock. When work is Delivered, accept it (Close) or ask for ', image_alt_bm='Contoh skrin (data contoh): Tekan satu permohonan untuk buka garis masa: perubahan status, mesej, fail dan jam SLA. Bila kerja Dihantar, terima (Tutup) atau minta Revis', order_index=3, deleted_at=null where lesson_id='28c2b0a4-e59b-452a-a2e8-bfc07162bad0' and step_no=3;
insert into public.learning_steps (id, lesson_id, step_no, order_index, text_en, text_bm, field_note_en, field_note_bm, try_it_page, image_path, image_alt_en, image_alt_bm)
 select 'd6268918-54bb-4eb3-a1b1-5b2ff30223ba', '28c2b0a4-e59b-452a-a2e8-bfc07162bad0', 3, 3, 'Tap a request to open its timeline: status changes, messages, files and the SLA clock. When work is Delivered, accept it (Close) or ask for a Revision.', 'Tekan satu permohonan untuk buka garis masa: perubahan status, mesej, fail dan jam SLA. Bila kerja Dihantar, terima (Tutup) atau minta Revisi.', 'Delivered requests close automatically 7 days after delivery.', 'Permohonan Dihantar ditutup automatik 7 hari selepas dihantar.', 'servis_saya', 'lc-img/sd_client/my-services-3.webp', 'Example screen (sample data): Tap a request to open its timeline: status changes, messages, files and the SLA clock. When work is Delivered, accept it (Close) or ask for ', 'Contoh skrin (data contoh): Tekan satu permohonan untuk buka garis masa: perubahan status, mesej, fail dan jam SLA. Bila kerja Dihantar, terima (Tutup) atau minta Revis'
