 select 'ad856d71-2807-442d-a0fa-d0d66125270d', '28c2b0a4-e59b-452a-a2e8-bfc07162bad0', 4, 4, 'Use the New request button to send work. Only services in your contract are listed.', 'Guna butang Permohonan baharu untuk hantar kerja. Hanya servis dalam kontrak anda disenaraikan.', NULL, NULL, 'servis_saya', 'lc-img/sd_client/my-services-4.webp', 'Example screen (sample data): Use the New request button to send work. Only services in your contract are listed.', 'Contoh skrin (data contoh): Guna butang Permohonan baharu untuk hantar kerja. Hanya servis dalam kontrak anda disenaraikan.'
