insert into public.learning_lessons (id, chapter_id, sort_order, order_index, title_en, title_bm, intro_en, intro_bm) values ('c628287f-77b5-4886-a40e-62d2f55ebf08', '848cf8e1-ee8d-4462-a285-56cf1d468a03', 2, 2, 'New request: one or many services', 'Permohonan baharu: satu atau banyak servis', 'You can send up to 5 services in one go. Two or more services become a group (SG-…) with one request (SR-…) per service; one service stays a normal request.', 'Anda boleh hantar sehingga 5 servis sekali gus. Dua atau lebih servis jadi satu kumpulan (SG-…) dengan satu permohonan (SR-…) setiap servis; satu servis kekal permohonan biasa.')
