update public.learning_steps set text_en='Step 1: tick the services you need (max 5). If a service already has an open request, choose "Add to existing SR" to add a note there instead of opening a duplicate.', text_bm='Langkah 1: tanda servis yang perlu (maks 5). Jika servis itu sudah ada permohonan terbuka, pilih "Tambah ke SR sedia ada" untuk tambah nota di situ dan elak pendua.', field_note_en='If the monthly quota cannot cover every service, the last ones are skipped with a warning; the others are still sent.', field_note_bm='Jika kuota bulanan tidak cukup untuk semua servis, yang terakhir diskip dengan amaran; yang lain tetap dihantar.', try_it_page='servis_saya', image_path='lc-img/sd_client/multi-request-1.webp', image_alt_en='Example screen (sample data): Step 1: tick the services you need (max 5). If a service already has an open request, choose "Add to existing SR" to add a note there instea', image_alt_bm='Contoh skrin (data contoh): Langkah 1: tanda servis yang perlu (maks 5). Jika servis itu sudah ada permohonan terbuka, pilih "Tambah ke SR sedia ada" untuk tambah nota ', order_index=1, deleted_at=null where lesson_id='c628287f-77b5-4886-a40e-62d2f55ebf08' and step_no=1;
