update public.learning_steps set text_en='Step 2: fill in the title, details and priority. "Use same details for all" copies them to every service; switch it off to write per service. Shared attachments are linked to every request.', text_bm='Langkah 2: isi tajuk, butiran dan keutamaan. "Guna butiran sama untuk semua" menyalin ke setiap servis; matikan untuk tulis setiap servis. Lampiran berkongsi dipaut ke setiap permohonan.', field_note_en=NULL, field_note_bm=NULL, try_it_page='servis_saya', image_path='lc-img/sd_client/multi-request-2.webp', image_alt_en='Example screen (sample data): Step 2: fill in the title, details and priority. "Use same details for all" copies them to every service; switch it off to write per service', image_alt_bm='Contoh skrin (data contoh): Langkah 2: isi tajuk, butiran dan keutamaan. "Guna butiran sama untuk semua" menyalin ke setiap servis; matikan untuk tulis setiap servis. L', order_index=2, deleted_at=null where lesson_id='c628287f-77b5-4886-a40e-62d2f55ebf08' and step_no=2;
