update public.learning_steps set text_en='Step 3: review the list, warnings and SLA, tick "Save as template" if you send this combo often, then Submit.', text_bm='Langkah 3: semak senarai, amaran dan SLA, tanda "Simpan sebagai templat" jika kerap hantar kombinasi ini, kemudian Hantar.', field_note_en='Your draft is saved automatically, so you can come back later and tap Resume.', field_note_bm='Draf anda disimpan automatik, jadi anda boleh kembali kemudian dan tekan Sambung.', try_it_page='servis_saya', image_path='lc-img/sd_client/multi-request-3.webp', image_alt_en='Example screen (sample data): Step 3: review the list, warnings and SLA, tick "Save as template" if you send this combo often, then Submit.', image_alt_bm='Contoh skrin (data contoh): Langkah 3: semak senarai, amaran dan SLA, tanda "Simpan sebagai templat" jika kerap hantar kombinasi ini, kemudian Hantar.', order_index=3, deleted_at=null where lesson_id='c628287f-77b5-4886-a40e-62d2f55ebf08' and step_no=3;
