update public.learning_steps set text_en='A group card shows progress such as 2/3 done. Open it to see each request, the group thread, cancel one request, or rate the whole group when everything is done.', text_bm='Kad kumpulan tunjuk kemajuan seperti 2/3 siap. Buka untuk lihat setiap permohonan, thread kumpulan, batal satu permohonan, atau beri rating kumpulan bila semua siap.', field_note_en='Edit services is locked once M-Core assigns a PIC.', field_note_bm='Ubah servis dikunci sebaik M-Core tetapkan PIC.', try_it_page='servis_saya', image_path='lc-img/sd_client/multi-request-4.webp', image_alt_en='Example screen (sample data): A group card shows progress such as 2/3 done. Open it to see each request, the group thread, cancel one request, or rate the whole group whe', image_alt_bm='Contoh skrin (data contoh): Kad kumpulan tunjuk kemajuan seperti 2/3 siap. Buka untuk lihat setiap permohonan, thread kumpulan, batal satu permohonan, atau beri rating ', order_index=4, deleted_at=null where lesson_id='c628287f-77b5-4886-a40e-62d2f55ebf08' and step_no=4;
