insert into public.learning_lessons (id, chapter_id, sort_order, order_index, title_en, title_bm, intro_en, intro_bm) values ('92bc642e-8f10-40b9-a98c-d183cbfe4236', '848cf8e1-ee8d-4462-a285-56cf1d468a03', 3, 3, 'Public link: requests without login', 'Link awam: permohonan tanpa log masuk', 'Owners and admins can share a link so customers or staff send requests without an account. Every public request waits for your approval.', 'Owner dan admin boleh kongsi link supaya pelanggan atau staf hantar permohonan tanpa akaun. Setiap permohonan awam menunggu kelulusan anda.')
